@pytest.mark.parametrize(('source_kind', 'zero_cut', 'body_raised', 'missing'), _MISSING, ids=tuple(row[-1] for row in _MISSING)) def test_second_round_missing_capture_never_borrows_the_complete_first_round( source_kind, zero_cut, body_raised, missing): program, model, details = _pipeline_capture(source_kind, zero_cut, body_raised, missing) index = _index(program, model, details) static = details['static'] report = _report(index, static) first, second = details['rounds'] assert first['caller_activation'] == second['caller_activation'] assert first['body_activation'] != second['body_activation'] _assert_round(program, model, index, report, static, first) assert report['status'] == 'PARTIAL' if missing in ('source-use', 'helper-call', 'inner-call'): selected = _selected_advances(report, static, second) assert selected assert all(row['status'] == 'PARTIAL' and row['gaps'] for row in selected) assert all(source['occurrence'].id != first['acquisition'] for row in selected for source in row['matched_sources']) codes = _codes(gap for row in selected for gap in row['gaps']) if missing == 'source-use': # The own result still identifies Get1. Its missing operand does # not erase that result or permit Get0 to supply the B input. for occurrence in selected: source, = occurrence['matched_sources'] assert source['occurrence'].id == second['acquisition'] assert source['body_input'] is None route, = occurrence['routes'] projection, = route['projections'] binding, = projection['bindings'] assert binding['source_value'] == source['value'] assert binding['formal'] == route['drive']['instance']['creation_handle'] assert binding['original_copy'] is False assert binding['compatibility']['status'] == 'UNPROVED' assert 'body_reference_identity_unproved' in codes assert any(gap.code == 'use_unobserved' and gap.path == str(second['acquisition']) for gap in index.report.gaps) elif missing == 'helper-call': assert 'await_general_body_source_occurrence_unproved' in codes else: assert 'await_drive_call_chain_missing' in codes assert all(row['routes'] == () for row in selected) elif missing == 'child-call': _, consumer = _consumer(report, static, second) implementation = consumer['implementation'] assert implementation['status'] == 'PARTIAL' assert len(implementation['frames']) == 2 assert implementation['frames'][0]['call']['association'] == second['implementation_root_call'] assert implementation['frames'][1]['call'] is None assert 'region_call_activation_unobserved' in _codes(implementation['frames'][1]['gaps']) elif missing == 'resume-transfer': association = second['body_drives'][1] drive = index.drive_execution(association.drive, budget=_BUDGET) assert drive['association'] == association and drive['activation'].id == second['body_activation'] assert drive['status'] == 'PARTIAL' assert 'body_resume_transfer_unobserved' in _codes(drive['gaps']) assert 'resume_transfer_unobserved' in _codes(index.report.gaps) elif missing == 'observer-state': current = index.occurrence(second['observer']) assert current['uses'][1] is None assert current['uses'][0] is not None and current['uses'][2] is not None assert index.occurrence(first['observer'])['uses'][1] is not None assert 'use_unobserved' in _codes(index.report.gaps) elif missing == 'observer-payload': actual = _actual_outcome(report, static, second) consumer, = tuple(row for row in actual['consumers'] if row['definition']['actual'] == second['ending']['observer_uses'][0]) assert consumer['selected'] is True and consumer['use'] is None assert consumer['binding']['match'] is None and consumer['status'] == 'PARTIAL' assert 'await_outcome_consumer_use_missing' in _codes(consumer['gaps']) else: > _, consumer = _consumer(report, static, second) ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
